"Postupak je pokrenut pisanim upozorenjem od {0} godine, dostavljenim zaposlenom uz rok od {1} dana za pisano izjašnjenje i pravo na usmeno izjašnjenje. {2} {3}utvrđeno je da je zaposleni učinio povredu iz dispozitiva, koja je u vrijeme izvršenja bila utvrđena ugovorom o radu i Pravilnikom (čl. 144 st. 4 ZOR).",
"Postupak nije pronađen.",
"Postupak po zakonu (",
"Postupak pokreće izvršni direktor po saznanju ili na inicijativu bilo kog zaposlenog, pisanim upozorenjem zaposlenom u roku od {0} dana od saznanja. Upozorenje sadrži lične podatke i radno mjesto zaposlenog, opis i vremenski okvir povrede, dokaze i naznaku prava na usmeno izjašnjenje. Zaposleni se pisano izjašnjava u roku od {1} dana od dostavljanja (ćutanje se smatra saglasnošću sa navodima), a u roku od {2} dana može zahtijevati usmeno izjašnjenje; rasprava se održava u roku od 15 dana od dostavljanja upozorenja, uz pravo zaposlenog na prisustvo sindikalnog predstavnika i branioca, i o njoj se vodi zapisnik ({3}). Odluku — o obustavi postupka, oslobađanju ili mjeri — donosi izvršni direktor u roku od {4} dana od isteka roka za izjašnjenje odnosno od rasprave (30 dana uz uviđaj ili vještačenje); odluka sadrži uvod, izreku, obrazloženje i pouku o pravnom lijeku, konačna je i dostavlja se u roku od {5} dana. Zaposleni je može osporiti u roku od {6} dana pred Agencijom za mirno rješavanje radnih sporova, a kod prestanka i uslovnog prestanka i pred sudom ({7}).",
"Postupak se može pokrenuti u roku od {0} mjeseca od saznanja za povredu i učinioca, a mora se okončati u roku od {1} mjeseca od pokretanja; ako povreda ima obilježja krivičnog djela, pokretanje je moguće u roku od 6 mjeseci od saznanja ({2}). Mjera se ne može izvršiti ako je proteklo {3} dana od konačnosti odluke a izvršenje nije započeto; opomena, novčana kazna i uslovni prestanak brišu se iz evidencije ako zaposleni u roku od {4} godine ne učini novu povredu ({5}). Novčana kazna obustavlja se od zarade po konačnoj odluci, tako da ukupne obustave bez saglasnosti zaposlenog ne pređu trećinu zarade ({6}).",
