"Pravilnik 34/12 čl. 11: promjena cijene robe upisuje se u evidenciju trgovine na osnovu izvještaja o izvršenom popisu. Povećanje se upisuje kao zaduženje, smanjenje crvenim stornom (kol. 4). Nova cijena važi od dana nivelacije u lageru i cjenovniku kase; istorija cijena ostaje (Zakon o zaštiti potrošača čl. 15).",
