"Revers nijedan propis ne pominje. Tumačenje bliže tekstu ZPDV čl. 4 st. 1 (promet je prenos prava raspolaganja): roba na reversu nije prodata i ostaje imovina firme; razdužuje se tek računom (Pravilnik 34/12 čl. 7 kol. 5), a povrat nema upisa u trgovačkoj knjizi. Lager: izlaz na dan izdavanja, ulaz na dan povrata. Drugo tumačenje: ako primalac robom raspolaže, isporuka je izvršena (PDV najkasnije 8 dana od predaje, ZPDV čl. 18 st. 3). Roba na reversu se popisuje na posebnoj popisnoj listi (Pravilnik o popisu, čl. 2).",
