"Zaposlenom pripada osnovna zarada za {0} radno vrijeme i standardni učinak u iznosu od {1} bruto mjesečno{2}, koja ne može biti niža od minimalne zarade za nivo kvalifikacije radnog mjesta ({3}: {4} EUR neto za radna mjesta do V nivoa, {5} EUR neto za VI i viši nivo){6}. Zaposleni ima pravo i na poseban dio zarade (naknada za topli obrok i 1/12 regresa za godišnji odmor) u skladu sa zakonom i opštim aktom Poslodavca.",
