"Zarada se isplaćuje u novcu, na tekući račun Zaposlenog {0}{1}, jednom mjesečno, najkasnije do {2}. u mjesecu za prethodni mjesec, uz pisani obračun zarade ({3}). Zaposleni ima pravo na naknadu troškova službenog putovanja i druga primanja u skladu sa zakonom i opštim aktom Poslodavca. Zaposleni ima pravo da iznosi podatke o sopstvenoj zaradi radi ostvarivanja prava na jednaku zaradu ({4}).",
